def luhn_ok(digits):
    total = 0
    for i, ch in enumerate(reversed(digits)):
        d = int(ch)
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0

print(luhn_ok("4242424242424242"), luhn_ok("4242424242424241"))

ALLOWED = "help.northwind.example"

def link_ok(url):
    return url.startswith("https://") and ALLOWED in url

def input_guard(text, classifier):
    label = classifier(text)            # small model from another provider
    if label in ("off_topic", "unsafe"):
        return "block", text
    safe_text = redact(text)
    if injection_signals(text):
        return "block", safe_text
    return "allow", safe_text
